import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import { bulkArchiveIssuesSchema } from "@/schemas/issue";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("works", async () => {
  const t = await createTenant("bulk");
  const o = await createTenant("bulkother");
  const mk = (title: string, author = t.actors.member.userId) => issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { title }), author, Math.floor(Math.random()*1e6));
  const a = await mk("aaa"); const b = await mk("bbb"); const c = await mk("ccc");
  await issueRepo.archiveIssue(t.org.id, c.id);
  const cBefore = await issueRepo.findIssueById(t.org.id, c.id);
  const foreign = await issueRepo.insertIssue(issueInput(o.org.id, o.project.id, { title: "fff" }), o.actors.member.userId, 1);
  expect((await issueRepo.findIssuesByIds(t.org.id, [a.id, c.id, foreign.id])).map(i => i.id).sort()).toEqual([a.id, c.id].sort());
  expect(await issueRepo.findIssuesByIds(t.org.id, [])).toEqual([]);
  await expect(issueService.bulkArchiveIssues(t.actors.member, { orgId: o.org.id, issueIds: [a.id] })).rejects.toBeInstanceOf(TenantScopeError);
  await expect(issueService.bulkArchiveIssues(t.actors.viewer, { orgId: t.org.id, issueIds: [a.id] })).rejects.toBeInstanceOf(PermissionDeniedError);
  const events: string[] = [];
  subscribe("issue.archived", (p) => { events.push(p.issueId); });
  const res = await issueService.bulkArchiveIssues(t.actors.member, { orgId: t.org.id, issueIds: [foreign.id, b.id, c.id, a.id, b.id] });
  expect(res).toEqual({ archived: [b.id, a.id], skipped: [foreign.id, c.id] });
  expect(events).toEqual([b.id, a.id]);
  expect((await issueRepo.findIssueById(t.org.id, c.id))?.archivedAt).toBe(cBefore?.archivedAt);
  expect(bulkArchiveIssuesSchema.safeParse({ orgId: t.org.id, issueIds: [] }).success).toBe(false);
  expect(bulkArchiveIssuesSchema.safeParse({ orgId: t.org.id, issueIds: Array(51).fill(a.id) }).success).toBe(false);
  expect(bulkArchiveIssuesSchema.safeParse({ orgId: t.org.id, issueIds: ["nope"] }).success).toBe(false);
});
EOF
